(7502292, 1195783, 140305, '<td valign="top">Phone camera? Turned into an interesting effect. I might have cropped the top to remove that left corner but that''s just me. Overall, I like it!</td>', 'Phone camera? Turned into an interesting effect. I might have cropped the top to remove that left corner but that''s just me. Overall, I like it!', '2017-02-26 13:03:09.000000', NULL, 1),
(7502293, 1195799, 140305, '<td valign="top">Wow, beautifully intense colours and I love the composition.</td>', 'Wow, beautifully intense colours and I love the composition.', '2017-02-26 13:04:12.000000', NULL, 1),
(7502294, 1195905, 140305, '<td valign="top">Gorgeous composition.</td>', 'Gorgeous composition.', '2017-02-26 13:04:49.000000', NULL, 1),
(7502295, 1195797, 140305, '<td valign="top">I think this might be a stronger image without the blurry tree on the right (it doesn''t really add to the image, in fact it''s rather distracting), just a square crop with just the person and the two close trees. Just my humble opinion.</td>', 'I think this might be a stronger image without the blurry tree on the right (it doesn''t really add to the image, in fact it''s rather distracting), just a square crop with just the person and the two close trees. Just my humble opinion.', '2017-02-26 13:10:49.000000', NULL, 1),
(7502297, 1195788, 140305, '<td valign="top">Love the tones and the very dark vignette. One of my faves.</td>', 'Love the tones and the very dark vignette. One of my faves.', '2017-02-26 13:13:23.000000', NULL, 1),
(7502298, 1195831, 140305, '<td valign="top">Breathe it in. Love that sparkle on the water and the simplicity of the processing.</td>', 'Breathe it in. Love that sparkle on the water and the simplicity of the processing.', '2017-02-26 13:16:33.000000', NULL, 1),
(7502299, 1195826, 140305, '<td valign="top">Dramatic simplicity. Love the colour tones in this image.</td>', 'Dramatic simplicity. Love the colour tones in this image.', '2017-02-26 13:18:21.000000', NULL, 1),
(7502300, 1195634, 140305, '<td valign="top">Like a gorgeous painting.</td>', 'Like a gorgeous painting.', '2017-02-26 13:20:02.000000', NULL, 1),
